ARTIFACT_DDL = ("CREATE TABLE qq_official_file_artifacts (\n    artifact_id TEXT PRIMARY KEY CHECK (artifact_id ~ '^[a-f0-9]{32}$'),\n    request_key TEXT NOT NULL UNIQUE CHECK (request_key ~ '^[a-f0-9]{64}$'),\n    account_key TEXT NOT NULL,\n    endpoint_key TEXT NOT NULL,\n    requester_actor_key TEXT NOT NULL,\n    source_execution_id TEXT NOT NULL,\n    source_task_id BIGINT REFERENCES qq_official_subagent_dispatches(task_id),\n    source_task_revision BIGINT,\n    source_canonical_message_id BIGINT NOT NULL,\n    source_native_message_id TEXT NOT NULL,\n    source_scope_key TEXT NOT NULL CHECK (octet_length(source_scope_key) BETWEEN 1 AND 1000),\n    source_job_id BIGINT NOT NULL REFERENCES durable_jobs(job_id),\n    source_job_lease_generation BIGINT NOT NULL CHECK (source_job_lease_generation>=1),\n    source_account_epoch BIGINT NOT NULL CHECK (source_account_epoch>=1),\n    endpoint_generation BIGINT NOT NULL CHECK (endpoint_generation>=1),\n    route_epoch BIGINT NOT NULL CHECK (route_epoch>=1),\n    sha256 TEXT NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),\n    byte_size BIGINT NOT NULL CHECK (byte_size BETWEEN 1 AND 104857600),\n    mime TEXT NOT NULL CHECK (mime IN ('application/pdf','application/zip')),\n    filename TEXT NOT NULL CHECK (octet_length(filename) BETWEEN 1 AND 180),\n    draft BOOLEAN NOT NULL,\n    draft_reason TEXT NOT NULL CHECK (octet_length(draft_reason)<=1000),\n    created_at BIGINT NOT NULL CHECK (created_at>=0),\n    pending_deadline_at BIGINT NOT NULL,\n    first_possible_send_at BIGINT,\n    retain_until BIGINT NOT NULL,\n    bytes_state TEXT NOT NULL DEFAULT 'available' CHECK (bytes_state IN ('available','deleted')),\n    bytes_deleted_at BIGINT,\n    cleanup_pending BOOLEAN NOT NULL DEFAULT FALSE,\n    cleanup_retry_at BIGINT NOT NULL DEFAULT 0 CHECK (cleanup_retry_at>=0),\n    UNIQUE(artifact_id,account_key,endpoint_key),\n    UNIQUE(artifact_id,requester_actor_key),\n    FOREIGN KEY(endpoint_key,account_key) REFERENCES qq_official_endpoints(endpoint_key,account_key),\n    FOREIGN KEY(source_execution_id,endpoint_key,requester_actor_key)\n        REFERENCES qq_official_turn_executions(execution_id,endpoint_key,requester_actor_key),\n    FOREIGN KEY(source_execution_id,source_canonical_message_id,source_native_message_id)\n        REFERENCES qq_official_turn_executions(execution_id,canonical_message_id,source_native_message_id),\n    FOREIGN KEY(source_task_id,endpoint_key,requester_actor_key)\n        REFERENCES subagent_tasks(task_id,endpoint_key,requester_actor_key),\n    CHECK ((source_task_id IS NULL)=(source_task_revision IS NULL)),\n    CHECK (source_task_revision IS NULL OR source_task_revision=1),\n    CHECK (draft OR draft_reason=''),\n    CHECK (pending_deadline_at>created_at AND pending_deadline_at-created_at<=86400),\n    CHECK (retain_until>=created_at AND retain_until<=pending_deadline_at),\n    CHECK (first_possible_send_at IS NULL OR\n        (first_possible_send_at>=created_at AND first_possible_send_at<pending_deadline_at\n         AND retain_until-first_possible_send_at<=3600)),\n    CHECK ((bytes_state='deleted')=(bytes_deleted_at IS NOT NULL)),\n    CHECK (NOT cleanup_pending OR bytes_state='deleted')\n)", "CREATE TABLE qq_official_file_deliveries (\n    artifact_id TEXT PRIMARY KEY REFERENCES qq_official_file_artifacts(artifact_id),\n    job_id BIGINT NOT NULL UNIQUE REFERENCES durable_jobs(job_id),\n    UNIQUE(artifact_id,job_id),\n    state TEXT NOT NULL DEFAULT 'stored' CHECK (state IN\n        ('stored','uploading','uploaded','upload_unknown','publishing','publication_unknown','published','handed_off',\n         'message_accepted','delivery_unknown','failed','cancelled','expired')),\n    route TEXT CHECK (route IN ('native','link')),\n    active_plan_id TEXT UNIQUE REFERENCES delivery_plans(plan_id),\n    publication_request_key TEXT UNIQUE CHECK (publication_request_key ~ '^[a-f0-9]{64}$'),\n    publication_started_at BIGINT,\n    publication_expires_at BIGINT,\n    CONSTRAINT ck_qq_file_publication_intent CHECK (\n        (publication_request_key IS NULL AND publication_started_at IS NULL AND publication_expires_at IS NULL)\n        OR (publication_request_key IS NOT NULL AND publication_started_at IS NOT NULL\n            AND publication_expires_at IS NOT NULL AND route IS NOT DISTINCT FROM 'link'\n            AND publication_started_at>=0 AND publication_expires_at>publication_started_at\n            AND publication_expires_at-publication_started_at<=3600)),\n    reason_code TEXT NOT NULL DEFAULT '' CHECK (reason_code='' OR reason_code ~ '^[a-z0-9_]{1,80}$'),\n    created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL,\n    CHECK ((state IN ('handed_off','message_accepted','delivery_unknown')) <= (active_plan_id IS NOT NULL))\n)", "CREATE FUNCTION qq_official_file_manifest_immutable() RETURNS trigger\nLANGUAGE plpgsql AS $$ BEGIN\n    IF ROW(NEW.artifact_id,NEW.request_key,NEW.account_key,NEW.endpoint_key,NEW.requester_actor_key,\n           NEW.source_execution_id,NEW.source_task_id,NEW.source_task_revision,\n           NEW.source_canonical_message_id,NEW.source_native_message_id,NEW.source_scope_key,\n           NEW.source_job_id,NEW.source_job_lease_generation,NEW.source_account_epoch,\n           NEW.endpoint_generation,NEW.route_epoch,NEW.sha256,NEW.byte_size,NEW.mime,NEW.filename,\n           NEW.draft,NEW.draft_reason,NEW.created_at,NEW.pending_deadline_at)\n       IS DISTINCT FROM\n       ROW(OLD.artifact_id,OLD.request_key,OLD.account_key,OLD.endpoint_key,OLD.requester_actor_key,\n           OLD.source_execution_id,OLD.source_task_id,OLD.source_task_revision,\n           OLD.source_canonical_message_id,OLD.source_native_message_id,OLD.source_scope_key,\n           OLD.source_job_id,OLD.source_job_lease_generation,OLD.source_account_epoch,\n           OLD.endpoint_generation,OLD.route_epoch,OLD.sha256,OLD.byte_size,OLD.mime,OLD.filename,\n           OLD.draft,OLD.draft_reason,OLD.created_at,OLD.pending_deadline_at)\n       OR NEW.retain_until>OLD.retain_until\n       OR (OLD.first_possible_send_at IS NOT NULL AND\n           NEW.first_possible_send_at IS DISTINCT FROM OLD.first_possible_send_at)\n       OR (OLD.bytes_state='deleted' AND NEW.bytes_state<>'deleted')\n    THEN RAISE EXCEPTION 'immutable_official_artifact'; END IF;\n    RETURN NEW;\nEND $$", 'CREATE TRIGGER qq_official_file_manifest_immutable\n    BEFORE UPDATE ON qq_official_file_artifacts FOR EACH ROW\n    EXECUTE FUNCTION qq_official_file_manifest_immutable()', "CREATE INDEX ix_qq_file_retention ON qq_official_file_artifacts(retain_until,artifact_id) WHERE bytes_state='available'", 'CREATE INDEX ix_qq_file_account_endpoint ON qq_official_file_artifacts(account_key,endpoint_key)')

PUBLICATION_SQL = "-- DDL proposal for root's single 0065 migration; NOT a standalone migration.\n-- Requires root-owned immutable qq_official_file_artifacts(artifact_id TEXT PK).\nCREATE TABLE qq_official_file_publications (\n    publication_ref TEXT PRIMARY KEY CHECK (publication_ref ~ '^[0-9a-f]{32}$'),\n    credential_ref TEXT NOT NULL UNIQUE CHECK (credential_ref ~ '^[0-9a-f]{32}$'),\n    request_key TEXT NOT NULL UNIQUE CHECK (request_key ~ '^[0-9a-f]{64}$'),\n    artifact_id TEXT NOT NULL REFERENCES qq_official_file_artifacts(artifact_id) ON DELETE RESTRICT\n        CHECK (artifact_id ~ '^[0-9a-f]{32}$'),\n    token_digest TEXT NOT NULL UNIQUE CHECK (token_digest ~ '^[0-9a-f]{64}$'),\n    wire_commitment TEXT NOT NULL CHECK (wire_commitment ~ '^[0-9a-f]{64}$'),\n    origin TEXT NOT NULL CHECK (octet_length(origin) BETWEEN 1 AND 1024),\n    created_at BIGINT NOT NULL CHECK (created_at >= 0),\n    expires_at BIGINT NOT NULL CHECK (expires_at >= 0),\n    state TEXT NOT NULL DEFAULT 'active' CHECK (state IN ('active','revoked','expired','deleted')),\n    served_complete_count BIGINT NOT NULL DEFAULT 0 CHECK (served_complete_count >= 0),\n    CONSTRAINT qq_file_publication_ttl CHECK (\n        expires_at > created_at AND expires_at - created_at <= 3600\n    )\n);\nCREATE INDEX qq_file_publication_due ON qq_official_file_publications(expires_at, publication_ref)\n    WHERE state='active';\n\nCREATE FUNCTION qq_file_publication_immutable() RETURNS trigger LANGUAGE plpgsql AS $$\nBEGIN\n    IF ROW(NEW.publication_ref, NEW.credential_ref, NEW.request_key, NEW.artifact_id,\n           NEW.token_digest, NEW.wire_commitment, NEW.origin, NEW.created_at, NEW.expires_at)\n        IS DISTINCT FROM\n       ROW(OLD.publication_ref, OLD.credential_ref, OLD.request_key, OLD.artifact_id,\n           OLD.token_digest, OLD.wire_commitment, OLD.origin, OLD.created_at, OLD.expires_at)\n    THEN\n        RAISE EXCEPTION 'file_publication_immutable';\n    END IF;\n    IF NEW.state IS DISTINCT FROM OLD.state\n       AND NOT ((OLD.state='active' AND NEW.state IN ('revoked','expired','deleted'))\n                OR (OLD.state IN ('revoked','expired') AND NEW.state='deleted'))\n    THEN\n        RAISE EXCEPTION 'file_publication_terminal';\n    END IF;\n    IF NEW.served_complete_count < OLD.served_complete_count\n       OR (NEW.served_complete_count IS DISTINCT FROM OLD.served_complete_count\n           AND NOT (OLD.state='active' AND NEW.state='active'))\n    THEN\n        RAISE EXCEPTION 'file_publication_observation_invalid';\n    END IF;\n    RETURN NEW;\nEND;\n$$;\nCREATE TRIGGER qq_file_publication_immutable_before_update\nBEFORE UPDATE ON qq_official_file_publications\nFOR EACH ROW EXECUTE FUNCTION qq_file_publication_immutable();\n"

CAPACITY_DDL = "CREATE TABLE qq_official_generation_capacity (\n    reservation_id TEXT PRIMARY KEY CHECK (reservation_id ~ '^[a-f0-9]{32}$'),\n    account_key TEXT NOT NULL REFERENCES qq_official_accounts(account_key),\n    endpoint_key TEXT NOT NULL,\n    requester_actor_key TEXT NOT NULL,\n    source_execution_id TEXT NOT NULL,\n    source_key TEXT NOT NULL CHECK (octet_length(source_key) BETWEEN 1 AND 160),\n    owner TEXT NOT NULL CHECK (owner ~ '^qqo:v1:[a-f0-9]{64}:x:[a-f0-9]{32}(:verify)?$'),\n    state TEXT NOT NULL CHECK (state IN ('reserved','released')),\n    created_at BIGINT NOT NULL CHECK (created_at>=0),\n    expires_at BIGINT NOT NULL CHECK (expires_at>created_at),\n    released_at BIGINT,\n    release_evidence TEXT CHECK (release_evidence IN ('owned_destroy','host_verified_absent')),\n    FOREIGN KEY(source_execution_id,endpoint_key,requester_actor_key)\n        REFERENCES qq_official_turn_executions(execution_id,endpoint_key,requester_actor_key),\n    FOREIGN KEY(endpoint_key,account_key) REFERENCES qq_official_endpoints(endpoint_key,account_key),\n    CHECK ((state='released')=(released_at IS NOT NULL)),\n    CHECK ((state='released')=(release_evidence IS NOT NULL))\n)"

